UPDATE whatsapp_ai_config
SET custom_prompt = replace(
  custom_prompt,
  E'    **Depois:**\n    "Excelente 👊\n    Seu benefício ficou registrado:\n    👤 Nome: [NOME COMPLETO]\n    🎁 Benefício: Curso profissionalizante EAD\n    📌 Status: Lista prioritária para futuras vagas presenciais\n    Assim que houver novas oportunidades na sua região, a equipe poderá entrar em contato.\n    Como combinado, vamos honrar nosso compromisso disponibilizando seu acesso ao curso EAD 👊🎁"\n    **IMPORTANTE — APÓS ESSA MENSAGEM, CHAME OBRIGATORIAMENTE A TOOL `send_promotional_image` com caption: "Segue o passo a passo para acessar seu curso EAD 👊🎁". Após a tool, NÃO envie mais nada — o card já contém o site, o cupom e o polo de ensino.**\n    *Encerrar.*',
  E'    **Depois que receber o nome completo, execute OBRIGATORIAMENTE estes 2 passos NESTA ORDEM:**\n\n    **PASSO 1 — ENVIAR ESTA MENSAGEM DE TEXTO PRIMEIRO (NÃO PULAR, NÃO RESUMIR):**\n    "Excelente 👊\n\n    Seu benefício ficou registrado:\n\n    👤 Nome: [NOME COMPLETO]\n\n    🎁 Benefício: Curso profissionalizante EAD\n\n    📌 Status: Lista prioritária para futuras vagas presenciais\n\n    Assim que houver novas oportunidades na sua região, a equipe poderá entrar em contato.\n\n    Como combinado, vamos honrar nosso compromisso disponibilizando seu acesso ao curso EAD 👊🎁"\n\n    **PASSO 2 — SOMENTE DEPOIS de enviar a mensagem acima, chame a tool `send_promotional_image` com caption: "Segue o passo a passo para acessar seu curso EAD 👊🎁". Após a tool, NÃO envie mais nada.**\n\n    ⚠️ REGRA CRÍTICA: É PROIBIDO chamar a tool `send_promotional_image` sem antes ter enviado a mensagem de texto do PASSO 1. A sequência correta é SEMPRE: texto do resumo → tool da imagem.\n    *Encerrar.*'
)
WHERE user_id = 'c753d23b-7f23-4d56-a867-6639897b6767';